#!/bin/sh
# Regenerates index.html as a single self-contained file (CSS + JS inlined from src/),
# so it can be uploaded or hosted on its own. Run after editing anything in src/.
set -e
cd "$(dirname "$0")"

python3 - <<'PY'
css = open('src/wave-header.css').read().strip()
js = open('src/wave-header.js').read().strip()

html = f"""<!doctype html>
<!-- GENERATED by build.sh from src/ — edit the files in src/, then run ./build.sh -->
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Dotted Wave Header</title>
<meta name="description" content="An interactive dotted-wave WebGL header.">
<link rel="icon" href="data:,">
<style>
html, body {{ margin: 0; background: #000; }}

{css}
</style>
</head>
<body>

<header data-wave-header></header>

<script>
{js}
</script>
</body>
</html>
"""
open('index.html', 'w').write(html)
print('wrote index.html (%d KB)' % (len(html) // 1024))
PY
